Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method ProcessHttpsRequest")

	set mshData = pRequest.mcKessonRetailHl7Msg.GetValueAt("MSH","",tSC)	
	set evnData = pRequest.mcKessonRetailHl7Msg.GetValueAt("EVN","",tSC)	
	set pidData = pRequest.mcKessonRetailHl7Msg.GetValueAt("PID","",tSC)	
	set dg1Data = pRequest.mcKessonRetailHl7Msg.GetValueAt("DG1","",tSC)
	set indexDg1 = $F(dg1Data, "DG1")    	  
	if (indexDg1 > 0){
	   set hl7Data = mshData_$CHAR(13)_evnData_$CHAR(13)_pidData_$CHAR(13)_dg1Data_$CHAR(13)
	}else{
		set hl7Data = mshData_$CHAR(13)_evnData_$CHAR(13)_pidData_$CHAR(13)
    }
	$$$TRACE("Hl7 Data1: "_hl7Data)


	Set httprequest=##class(%Net.HttpRequest).%New()
		set tSC = httprequest.Get()

	Set httprequest.Port = ..HttpPort
	Set httprequest.Server = ..HttpServer
	Set httprequest.Location = ..URL
	Set httprequest.SSLConfiguration = ..SSLConfig

	Set httprequest.Https="1"

	Set httprequest.ContentType="text/plain"	

	do httprequest.SetHeader("cookie",pRequest.authToken)

	Do httprequest.SetHeader("partnercode",pRequest.partnerCode) 	

    Do httprequest.EntityBody.Write(hl7Data)  

    try	{
     Set writer=##class(%Net.MIMEWriter).%New()
     Set status=writer.OutputToStream(httprequest.EntityBody)
     s postStatus = httprequest.Post(,2)    
    $$$TRACE("Resp Status:  "_postStatus)
    if (postStatus =1){
	    $$$TRACE(" McKesson Retail..Post Successful.")   
	    set len = httprequest.HttpResponse.ContentLength     
    	set respData = httprequest.HttpResponse.Data.Read()
    	$$$TRACE("RESP DATA ???? "_respData)   
    	set indexMSA = $F(respData, "MSA|AA")    	  
    	if (indexMSA > 0){
	    	$$$TRACE("SUCCESS!!!..Ack received from McKesson Retail. "_respData)   
		}else{
			$$$TRACE("ERROR!!!..NACK received from McKesson Retail. "_respData)   
		   set tSC = $$$ERROR(5922,"Exception. Not received successful acknowledgement from McKesson retail. Response received:"_respData)
		}
    }else{
	    set tSC = $$$ERROR(5922," Https Post Request failed. ")
	  }
    }
	catch e
	{
		$$$TRACE("Exception: " _ e)
		set tSC = $$$ERROR(5922,"Exception in McKessonRetail Operation")
	}


	quit tSC
